const body = $json.body ?? $json;
const papers = Array.isArray(body.papers) ? body.papers : [];
if (!papers.length) {
  throw new Error('Request body must include a non-empty papers array.');
}
const sectionNames = [
  'summarization',
  'gapDetection',
  'trendDetection',
  'visualization',
  'chatbot',
];
const analysisPrompt = `You are generating the ${sectionNames.length}-section research report for ResearchLens. Return valid JSON only with exactly these top-level keys: summarization, gapDetection, trendDetection, visualization, chatbot. Each section should be concise, evidence-based, and grounded in the provided paper summaries. Include a short reportTitle and reportSummary inside summarization if helpful.`;
const chatInput = `${analysisPrompt}

Question: ${body.question ?? 'What are the key findings, research gaps and emerging topics?'}

Papers: ${JSON.stringify(papers)}`;
return [{
  json: {
    papers,
    question: body.question ?? 'What are the key findings, research gaps and emerging topics?',
    reportName: body.reportName ?? 'ResearchLens AI Analysis Report',
    createdAt: new Date().toISOString(),
    sectionNames,
    analysisPrompt,
    chatInput,
  },
}];

const source = $json;
const candidateValues = [source.output, source.text, source.response, source.result, source.content];
let raw = candidateValues.find((value) => typeof value === 'string' && value.trim().length > 0);
if (!raw && source.message && typeof source.message === 'object') {
  raw = source.message.content ?? source.message.text;
}
if (!raw) {
  raw = JSON.stringify(source);
}
let parsed = raw;
if (typeof raw === 'string') {
  const trimmed = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  try {
    parsed = JSON.parse(trimmed);
  } catch (error) {
    parsed = { raw: trimmed };
  }
}
const summarization = parsed.summarization ?? parsed.summary ?? {};
const gapDetection = parsed.gapDetection ?? parsed.gaps ?? {};
const trendDetection = parsed.trendDetection ?? parsed.trends ?? {};
const visualization = parsed.visualization ?? parsed.chart ?? {};
const chatbot = parsed.chatbot ?? parsed.answer ?? {};
const reportMarkdown = [
  `# ${source.reportName ?? 'ResearchLens AI Analysis Report'}`,
  '',
  '## 1. Summarization',
  JSON.stringify(summarization, null, 2),
  '',
  '## 2. Gap Detection',
  JSON.stringify(gapDetection, null, 2),
  '',
  '## 3. Trend Detection',
  JSON.stringify(trendDetection, null, 2),
  '',
  '## 4. Visualization',
  JSON.stringify(visualization, null, 2),
  '',
  '## 5. Chatbot',
  JSON.stringify(chatbot, null, 2),
].join('\n');
return [{
  json: {
    id: `rpt_${Date.now()}`,
    createdAt: source.createdAt ?? new Date().toISOString(),
    reportName: source.reportName ?? 'ResearchLens AI Analysis Report',
    question: source.question,
    papersCount: Array.isArray(source.papers) ? source.papers.length : 0,
    analysisReport: {
      summarization,
      gapDetection,
      trendDetection,
      visualization,
      chatbot,
    },
    reportMarkdown,
  },
}];
